import React, { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
    Card,
    Table,
    Stack,
    Paper,
    TableRow,
    TableBody,
    TableCell,
    Typography,
    TableContainer,
} from '@mui/material';
import DateFormat from '../components/dayjsFormat/DateFormat';
// components
import Scrollbar from '../components/scrollbar';
// sections
import { UserListHead } from '../sections/@dashboard/user';
import { useMyContext } from './provider';
import GoBackButton from '../components/goBackButton/GoBackButton';

export default function TransactionDetails() {
    const navigate = useNavigate()
    const location = useLocation();
    const { data, ids } = location.state;
    const [order, setOrder] = useState('asc');
    const [selected, setSelected] = useState([]);
    const [orderBy, setOrderBy] = useState('name');
    const { i18 } = useMyContext();

    const TABLE_HEAD = [
        { id: 'amount', label: i18?.ACCOUNTSTITLE?.AMOUNT || 'Amount', alignRight: false },
        { id: 'createdAt', label: i18?.ACCOUNTSTITLE?.CREATED_AT || 'CreatedAt', alignRight: false },
        { id: 'description', label: i18?.ACCOUNTSTITLE?.DESCRIPTION || 'Description', alignRight: false },
        { id: 'type', label: i18?.ACCOUNTSTITLE?.PAYMENT_TYPE || 'Payment Type', alignRight: false },
        { id: 'balance', label: i18?.ACCOUNTSTITLE?.CURRENT_BALANCE || 'Current Balance', alignRight: false },
    ];
    const handleRequestSort = (event, property) => {
        const isAsc = orderBy === property && order === 'asc';
        setOrder(isAsc ? 'desc' : 'asc');
        setOrderBy(property);
    };
    const backtouser = () => {
        navigate('/dashboard/TransactionHistory', { state: { ids } });
    };
    return (
        <>
            <Helmet>
                <title> User | Admin panel </title>
            </Helmet>
            <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
                <Typography variant="h4" gutterBottom>
                    {i18?.ACCOUNTSTITLE?.TRANSACTION_DETAILS || "Transaction Details"}
                </Typography>
                <GoBackButton
                    label={i18?.ACCOUNTSTITLE?.GO_BACK || "Go Back"}
                    onClick={backtouser}
                    icon="icon-park-twotone:back"
                />
            </Stack>
            <Card>
                <Scrollbar>
                    <TableContainer sx={{ minWidth: 800 }}>
                        <Table>
                            <UserListHead
                                rder={order}
                                orderBy={orderBy}
                                headLabel={TABLE_HEAD}
                                rowCount={data?.length}
                                numSelected={selected?.length}
                                onRequestSort={handleRequestSort}
                            />
                            <TableBody>
                                {data?.map((row) => {
                                    const { id } = row;
                                    return (
                                        <TableRow
                                            sx={{
                                                '&:nth-of-type(odd)': {
                                                    backgroundColor: '#DDDDDD',
                                                },
                                                '&:last-child td, &:last-child th': {
                                                    border: 0,
                                                },
                                            }}
                                            key={id}
                                            tabIndex={-1}
                                            role="checkbox"
                                        >
                                            <TableCell padding="checkbox">
                                                {/* <Checkbox checked={selectedUser} onChange={(event) => handleClick(event, name)} /> */}
                                            </TableCell>
                                            <TableCell align="left">{row.amount}</TableCell>
                                            <TableCell align="left">{DateFormat(row?.createdAt)}</TableCell>
                                            <TableCell align="left">{row.description ? row.description : '--'}</TableCell>
                                            <TableCell align="left">{row.type ? row.type : '--'}</TableCell>
                                            <TableCell align="left">{row.currentBalance}</TableCell>
                                        </TableRow>
                                    );
                                })}
                            </TableBody>

                            {data?.length === 0 && (
                                <TableBody>
                                    <TableRow>
                                        <TableCell align="center" colSpan={12} sx={{ py: 3 }}>
                                            <Paper
                                                sx={{
                                                    textAlign: 'center',
                                                }}
                                            >
                                                <Typography variant="h6" paragraph>
                                                    {i18?.ACCOUNTSTITLE?.NO_DATA_FOUND || "No data found"}
                                                </Typography>
                                            </Paper>
                                        </TableCell>
                                    </TableRow>
                                </TableBody>
                            )}
                        </Table>
                    </TableContainer>
                </Scrollbar>
            </Card>
        </>
    );
}
